    if lexer is None:
        return [(code, None)]
    tokens = list(lex(code, lexer))
    calls = _call_names(tokens)
    out: List[Tuple[str, Optional[str]]] = []
    for i, (ttype, value) in enumerate(tokens):
        if not value:
            continue
