            ic = QLabel()
            ic.setPixmap(icons.pixmap(ico, getattr(t, name), 14))
            stl.addWidget(ic)
            lb = label(lab, size="small", tone="text_2" if tone == "ok" else name)
            stl.addWidget(lb)
