        self._focused = False
        self._fig = ("", "")  # (cost and agents, elapsed): the figures line is set when either changes
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAccessibleName("Open the session")
        self.setAutoDefault(False)
