        self.bg, self.line, self.radius, self.line_w = bg, line, radius, line_w
        bind(theme.theme.changed, self, lambda _t: self.update())

    def set_look(self, **kw: Any) -> None:
        for k, v in kw.items():
            setattr(self, k, v)
