            if t in (QEvent.Type.Show, QEvent.Type.WinIdChange):
                self._attach()
            elif t == QEvent.Type.WindowStateChange and (self._win.isMaximized() or self._win.isFullScreen()):
                self._set_cursor(Qt.Edges())
