export function normalizeWord(w) {
  return String(w || '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/^@/, '')
    .replace(/[\s_-]+/g, '');
}

function distance(a, b) {
  if (a === b) return 0;
