    }
  }
}

export function describeCadence(c) {
  const t = c?.time || '09:00';
  switch (c?.kind) {
    case 'hourly':
      return 'Every hour';
    case 'interval':
      return `Every ${c.everyHours || 1} hours`;
    case 'weekdays':
      return `Weekdays at ${t}`;
    case 'weekly':
      return `${['Sundays', 'Mondays', 'Tuesdays', 'Wednesdays', 'Thursdays', 'Fridays', 'Saturdays'][c.weekday ?? 1]} at ${t}`;
    case 'cron':
