}

/** pilcrow.log moves to pilcrow.log.1 (replacing the one before) past this, at start or while running. */
export const LOG_MAX_BYTES = 4 * 1024 * 1024;
let logStream = null;
let logBytes = 0;

const logFile = () => path.join(xdg('state'), 'pilcrow.log');

function openLog() {
  const file = logFile();
