        .catch(() => seq === planSeq.current && setPlanning(false));
    }, 600);
    return () => clearTimeout(t);
  }, [values, targets.length]);
  const verdicts = useMemo(() => Object.fromEntries((plan?.targets || []).map((t) => [t.path, t])), [plan]);
