  const sessionsLoaded = useStore((s) => s.sessionsLoaded);
  const activeId = useStore((s) => s.activeId);
  const unread = useStore((s) => s.unread);
  const page = useStore((s) => s.page);
  const inboxUnread = useStore((s) => s.inboxUnread);
  // a number, so a run's progress (a new jobs map ten times a second) does not re-render the list
  const dispatchNeedsN = useStore((s) => dispatchNeeds(s.jobs));
  const config = useStore((s) => s.config);
  const info = useStore((s) => s.info);
  const showArchived = useStore((s) => s.ui.showArchived);
  const sidebarW = useStore((s) => s.ui.sidebarW);
  const [q, setQ] = useState('');
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  const [showAll, setShowAll] = useState<Record<string, boolean>>({});
  const now = useNow(30_000);
  const list = useRef<HTMLElement>(null);
  // What can move the rows besides the list itself: a search, a group folded, the archive shown, the selection.
  const layout = useMemo(() => [q, collapsed, showAll, showArchived, activeId], [q, collapsed, showAll, showArchived, activeId]);
  useFlip(list, sessions, layout);

  const { attention, pinned, groups, archivedCount, helpers } = useMemo(() => {
    let list = sessions.filter((s) => (showArchived ? s.archived : !s.archived));
    // Runs started by a schedule live in the inbox; the active one still shows so its row can be found.
    if (!q.trim()) list = list.filter((s) => (!s.scheduled && !s.dispatch) || s.id === activeId);
    if (q.trim()) list = list.filter((s) => fuzzyScore(q, `${s.title} ${basename(s.project || s.cwd)}`));
    // A lead's helpers sit under it, indented (HELPERS.md §6.3); a helper whose lead is not listed stays
    // where its folder puts it. The open one stays under its lead too: pulled out into its folder's
    // project, the helper on screen looked unrelated to its lead.
    const listed = new Set(list.map((s) => s.id));
    const helperMap = new Map<string, SessionSummary[]>();
    for (const s of list) {
      if (s.helper && listed.has(s.helper.leadId)) {
        const under = helperMap.get(s.helper.leadId) || [];
        helperMap.set(s.helper.leadId, [...under, s]);
      }
    }
    const nested = new Set([...helperMap.values()].flat().map((s) => s.id));
    list = list.filter((s) => !nested.has(s.id));
    // The conversation on screen never jumps into "Needs you": you are already looking at it, and its
    // row shows the amber mark where it is. Only other sessions gather there.
    const attention = list.filter((s) => s.id !== activeId && (s.status === 'requires_action' || (s.pending || 0) > 0));
    const pinned = list.filter((s) => s.pinned && !attention.includes(s));
    const rest = list.filter((s) => !attention.includes(s) && !pinned.includes(s));
    const map = new Map<string, Group>();
