          <Archive size={15} />
        </button>
        <button className="icon-btn" title={`Appearance: ${theme} — click for ${nextTheme}`} aria-label={`Appearance: ${theme} — click for ${nextTheme}`} onClick={(e) => setTheme(nextTheme, { x: e.clientX, y: e.clientY })}>
