      )}
    </>
  );
});

// ---------------------------------------------------------------- turns: the work folds, what Claude says stays

const WorkFold = memo(function WorkFold({ unit, ctx }: { unit: Extract<Unit, { kind: 'work' }>; ctx: ToolCtx }) {
