  return hlPromise;
}

async function ensureLang(lang: string) {
  if (loaded.has(lang)) return;
  if (!loading.has(lang)) {
    loading.set(
      lang,
      (async () => {
        const hl = await highlighter();
        const mod = (await LANGS[lang]()) as { default?: unknown };
