  cat > "$D"/'web/src/styles/dispatch.css' <<'PILCROW_EOF_36d6a2bd5f'
/* ================================================================ dispatch
   One job across many repositories (DISPATCH.md). The board follows the control room's shapes; the
   job view is one row per repository, the state carried by a glyph and a colour, never by a position;
   the composer is the dialog forms laid out as a page. */
.dispatch {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.dp-body {
  gap: var(--sp-5_5);
}
.dp-form {
  max-width: 920px;
  margin: 0 auto;
  width: 100%;
}
.dp-form > .field + .field,
.dp-form > .ns-two,
.dp-form > .dp-inline,
.dp-form > .dp-box {
  margin-top: 0;
}

/* ---- the job card */
.dp-card {
  gap: var(--sp-2);
}
.dp-line {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-width: 0;
}
.dp-name {
  font-weight: 600;
  flex: none;
  max-width: 40%;
}
.dp-scope {
  flex: none;
  font-size: var(--fs-small);
}
.dp-counts {
  flex: none;
  font-size: var(--fs-small);
  color: var(--text-2);
}
.dp-cost {
  flex: none;
  font-size: var(--fs-small);
}
.dp-bar {
  display: flex;
  gap: var(--sp-0_5);
  height: 6px;
  flex: 1 1 120px;
  max-width: 220px;
}
.dp-seg {
  flex: 1;
  border-radius: 2px;
  background: var(--fill-2);
}
.dp-seg.done {
  background: var(--ok);
}
.dp-seg.running,
.dp-seg.preparing {
  background: var(--accent);
}
.dp-seg.needs_action {
  background: var(--warn);
}
.dp-seg.failed {
  background: var(--err);
}
.dp-seg.stopped {
  background: var(--text-3);
}

/* ---- a request waiting, the canary waiting: on the board, wells inside the job's card (the control
   room's `.ovc-well`); in the job view, cards of their own (`.ovc.needs`) */
.ovc-well.dp-ask,
.ovc-well.dp-canary {
  align-items: center;
  gap: var(--sp-2_5);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-1_5) var(--sp-2_5);
}
.ovc-well.dp-ask .ovc-perm-what {
  flex: 1 1 auto;
  white-space: nowrap;
}
.dp-ask-who {
  flex: none;
  font-size: var(--fs-micro);
}
.dp-canary-text b {
  font-weight: 560;
}
.dp-card.needs {
  cursor: pointer;
}
.dp-learn {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
}

/* ---- the finished rows: the overview row without its mark column */
.dp-fin {
  width: 100%;
  cursor: pointer;
  grid-template-columns: minmax(0, 1fr) auto;
}

/* ---- the job view */
.status-pill.review,
.status-pill.paused {
  color: var(--text-3);
}
.dp-top {
  display: grid;
  gap: var(--sp-2);
  padding: var(--sp-1_5) var(--sp-5) var(--sp-2);
}
.dp-box {
  display: grid;
  gap: var(--sp-1);
  padding: var(--sp-2_25) var(--sp-3);
  border-radius: var(--r-4);
  background: var(--card);
  box-shadow: inset 0 0 0 0.5px var(--hair);
}
.dp-box-h {
  display: flex;
  align-items: baseline;
  gap: var(--sp-2_5);
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
  letter-spacing: 0.02em;
}
.dp-box-h b {
  font-size: var(--fs-ui);
  color: var(--text);
}
.dp-brief {
  margin: 0;
  font-size: var(--fs-small);
  line-height: 1.5;
  color: var(--text-2);
  white-space: pre-wrap;
}
.dp-rules {
  font-size: var(--fs-micro);
}
.dp-runs {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 0 var(--sp-3);
}
.dp-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-small-plus);
}
.dp-table th {
  position: sticky;
  top: 0;
  background: var(--canvas);
  text-align: left;
  font-size: var(--fs-tiny-plus);
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-3);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-2);
  border-bottom: 1px solid var(--hair);
}
.dp-table th.num,
.dp-table td.num {
  text-align: right;
}
.dp-table td {
  padding: var(--sp-1_75) var(--sp-2);
  border-bottom: 1px solid var(--hair);
  white-space: nowrap;
  vertical-align: middle;
}
.dp-row {
  cursor: pointer;
}
.dp-row:hover td {
  background: var(--fill-1);
}
/* on the hovered row's fill --text-3 falls short of 4.5:1 (tokens.css) */
.dp-row:hover .faint,
.dp-row:hover .dp-word.queued,
.dp-row:hover .dp-word.skipped,
.dp-row:hover .dp-word.stopped {
  color: var(--text);
}
.dp-row.needs_action td {
  background: var(--warn-wash);
}
.dp-state {
  width: 112px;
  white-space: nowrap;
}
.dp-state .dp-glyph {
  margin-right: var(--sp-2);
  vertical-align: middle;
}
.dp-word {
  vertical-align: middle;
}
.dp-word.done {
  color: var(--ok);
}
.dp-word.failed {
  color: var(--err);
}
.dp-word.running,
.dp-word.preparing {
  color: var(--accent-text);
}
.dp-word.needs_action {
  color: var(--warn);
}
.dp-word.queued,
.dp-word.skipped,
.dp-word.stopped {
  color: var(--text-3);
}
.dp-repo {
  font-weight: 500;
}
.dp-now {
  color: var(--text-2);
  max-width: 420px;
}
.dp-now > .ellipsis {
  display: inline-block;
  max-width: 260px;
  vertical-align: middle;
}
.dp-now.ok {
  color: var(--ok);
}
.dp-now.err {
  color: var(--err);
}
.dp-acts {
  display: inline-flex;
  gap: var(--sp-1_5);
  margin-left: var(--sp-2);
  vertical-align: middle;
}
.dp-glyph {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex: none;
  background: var(--text-4);
}
.dp-glyph.done {
  background: var(--ok);
}
.dp-glyph.running,
.dp-glyph.preparing {
  background: var(--accent);
}
.dp-glyph.needs_action {
  background: var(--warn);
}
.dp-glyph.failed {
  background: var(--err);
}
.dp-glyph.stopped {
  background: var(--text-3);
}
.dp-glyph.queued,
.dp-glyph.skipped {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px var(--text-4);
}
.dp-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5) var(--sp-2_5);
  border-top: 1px solid var(--hair);
  font-size: var(--fs-small);
  color: var(--text-2);
}

/* ---- the composer */
.dp-label-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2_5);
}
.dp-label-line .faint {
  font-size: var(--fs-small);
  font-weight: 400;
}
.dp-form .ns-disclose {
  margin: 0;
}
.dp-options {
  display: grid;
  gap: var(--sp-4_5);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-1);
}
.dp-group {
  display: grid;
  gap: var(--sp-2);
}
.dp-group-h {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-2);
}
.dp-box.dp-plan {
  padding: var(--sp-2_25) var(--sp-3);
}
.dp-inline {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  flex-wrap: wrap;
}
.dp-model {
  max-width: 220px;
}
.dp-targets-top {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
}
.dp-folder {
  max-width: 260px;
}
.dp-targets {
  display: grid;
  gap: var(--sp-0_5);
  padding: var(--sp-1_5);
  border-radius: var(--r-4);
  background: var(--inset);
  box-shadow: inset 0 0 0 0.5px var(--hair);
  max-height: 320px;
  overflow: auto;
}
.dp-target {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-1);
  border-radius: var(--r-2);
}
.dp-target:hover {
  background: var(--fill-1);
}
/* on the hovered row's fill --text-3 falls short of 4.5:1 in the light theme (tokens.css) */
.dp-target:hover .faint {
  color: var(--text);
}
.dp-target-main {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  min-width: 0;
  height: 30px;
  padding: 0 var(--sp-1_5);
  cursor: pointer;
  font-size: var(--fs-ui);
}
.dp-target-main input {
  accent-color: var(--accent);
}
.dp-target-name {
  font-weight: 500;
}
.dp-notes {
  grid-column: 1 / -1;
  margin: 0 var(--sp-1_5) var(--sp-1_5) var(--sp-7_5);
}
.dp-chip {
  font-size: var(--fs-micro);
  font-weight: 600;
  padding: 1px var(--sp-1_75);
  border-radius: 9px;
  background: var(--fill-2);
  color: var(--text-2);
  white-space: nowrap;
}
.dp-chip.ok {
  background: var(--ok-wash);
  color: var(--ok);
}
.dp-chip.warning {
  background: var(--warn-wash);
  color: var(--warn);
}
.dp-chip.blocked {
  background: var(--err-wash);
  color: var(--err);
}
.dp-chip.info {
  background: var(--info-wash);
  color: var(--info);
}
.dp-plan-row {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: var(--sp-2_5);
  font-size: var(--fs-small);
  color: var(--text-2);
  line-height: 1.45;
}
.dp-plan-tag {
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
}
.dp-plan-tag.blocked {
  color: var(--err);
}
.dp-plan-tag.warning {
  color: var(--warn);
}

/* ---- the inbox card */
.dp-report .run-foot {
  flex-wrap: wrap;
  row-gap: var(--sp-1_5);
}
.dp-report .run-foot .ellipsis {
  min-width: 0;
  flex: 1 1 160px;
}
.dp-report-rows {
  display: grid;
  gap: var(--sp-0_5);
}
.dp-report-row {
  display: grid;
  grid-template-columns: 12px 150px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-2_5);
  font-size: var(--fs-small);
}
.dp-report-name {
  font-weight: 500;
}
.dp-report-nums {
  font-size: var(--fs-micro);
}
.dp-prose {
  white-space: pre-wrap;
}
