}
.ov-empty {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  padding: var(--sp-3_5) var(--sp-4);
  border-radius: var(--r-5);
  background: var(--fill-1);
  color: var(--text-2);
  font-size: var(--fs-small);
  line-height: 1.5;
}
.ov-empty > svg {
  flex: none;
  color: var(--text-3);
}

/* ---- cards */
.ovc {
  position: relative;
  display: grid;
  gap: var(--sp-2_25);
  padding: var(--sp-3_25) 15px var(--sp-3);
  border-radius: var(--r-6);
  background: var(--card);
  box-shadow: var(--card-shadow);
  text-align: left;
  cursor: pointer;
}
.ovc:hover {
  box-shadow: var(--card-shadow-hover);
}
.ovc.focused {
  box-shadow: 0 0 0 1.5px var(--text-3);
}
.ovc.needs {
