/* ================================================================ settings
   Settings: the layout and rows, the model picker, skills and MCP servers, project memory, and
   repositories. */

/* settings */
.settings .dialog-body {
  padding: 0;
  display: block;
}
.settings-layout {
  display: grid;
  grid-template-columns: 172px 1fr;
  height: min(480px, 64vh);
}
.settings-nav {
  display: grid;
  align-content: start;
  gap: 1px;
  padding: var(--sp-1_5) var(--sp-2_5) var(--sp-3_5) var(--sp-3_5);
}
.settings-nav button {
  height: 30px;
  padding: 0 var(--sp-2_5);
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
}
.settings-nav button:hover {
  background: var(--fill-1);
  color: var(--text);
}
.settings-nav button.on {
  background: transparent;
  color: var(--text);
  font-weight: 550;
}
.settings-body {
  padding: 0 var(--sp-5_5) var(--sp-5) var(--sp-2_5);
  display: grid;
  align-content: start;
  min-height: 0;
  overflow-y: auto;
}
.set-row {
  display: grid;
  grid-template-columns: 1fr minmax(180px, 46%);
  align-items: center;
  gap: var(--sp-5);
  padding: var(--sp-3_25) 0;
}
.set-row + .set-row {
  box-shadow: 0 -1px 0 var(--hair);
}
.set-label > div:first-child {
  font-weight: 500;
}
.set-label .hint {
  margin-top: var(--sp-0_5);
}
.set-control {
  display: flex;
  justify-content: flex-end;
}
/* Field-like controls fill the column so their left edges line up row to row. */
.set-control > .select-btn,
.set-control > .input {
  flex: 1;
  min-width: 0;
}
.settings-about {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-5_5) var(--sp-3_5);
  font-size: var(--fs-micro);
  color: var(--text-3);
  box-shadow: 0 -1px 0 var(--hair);
}
.diag {
